(window.KOTOBA_HK=window.KOTOBA_HK||{})[23]={"n":23,"S":[{"id":"l23a","ti":[[["うそつき","うそつき"],["少年","しょうねん"],["と","と"],["森","もり"],["の","の"],["オオカミ","オオカミ"]]],"tt":{"az":"Yalançı oğlan və meşədəki canavar","en":"The Boy Who Lied and the Wolf in the Forest","ru":"Мальчик-лжец и волк в лесу"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["小さな","ちいさな"],["村","むら"],["に","に"],["、"],["羊","ひつじ"],["の","の"],["世話","せわ"],["を","を"],["する","する","する",5],["少年","しょうねん"],["が","が"],["いました","いました","いる",2],["。"],["少年","しょうねん"],["は","は"],["毎朝","まいあさ"],["、"],["村","むら"],["を","を"],["出て","でて","出る",3],["、"],["山","やま"],["の","の"],["道","みち"],["を","を"],["歩きました","あるきました","歩く",2],["。"],["天気","てんき"],["が","が"],["いい","いい"],["とき","とき"],["、"],["羊たち","ひつじたち"],["は","は"],["草","くさ"],["を","を"],["食べて","たべて","食べる",3],["、"],["少年","しょうねん"],["は","は"],["木","き"],["の","の"],["下","した"],["で","で"],["休みました","やすみました","休む",2],["。"],["でも","でも"],["、"],["一人","ひとり"],["の","の"],["とき","とき"],["は","は"],["、"],["とても","とても"],["寂しかった","さびしかった","寂しい",0],["です","です"],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, kiçik bir kənddə qoyunlara baxan bir oğlan yaşayırdı. Oğlan hər səhər kənddən çıxıb dağ yolunda yeriyirdi. Hava yaxşı olanda qoyunlar ot yeyir, oğlan isə ağacın altında dincəlirdi. Amma tək qalanda özünü çox tənha hiss edirdi.","en":"Long, long ago, a boy who looked after sheep lived in a small village. Every morning, he left the village and walked along a mountain path. When the weather was nice, the sheep ate grass, and the boy rested under a tree. But when he was alone, he felt very lonely.","ru":"Давным-давно в маленькой деревне жил мальчик, который пас овец. Каждое утро он выходил из деревни и шёл по горной тропинке. Когда погода была хорошей, овцы ели траву, а мальчик отдыхал под деревом. Но когда он оставался один, ему было очень одиноко."}},{"t":[[["ある日","あるひ"],["、"],["少年","しょうねん"],["は","は"],["おもしろい","おもしろい"],["こと","こと"],["を","を"],["考えました","かんがえました","考える",2],["。"],["山","やま"],["から","から"],["村","むら"],["を","を"],["見る","みる","見る",5],["と","と"],["、"],["人","ひと"],["が","が"],["たくさん","たくさん"],["歩いていました","あるいていました","歩く",15],["。"],["少年","しょうねん"],["は","は"],["大きな","おおきな"],["声","こえ"],["で","で"],["「"],["オオカミ","オオカミ"],["だ","だ","です"],["！"],["助けて","たすけて","助ける",3],["！"],["」"],["と","と"],["何回","なんかい"],["も","も"],["叫びました","さけびました","叫ぶ",2],["。"],["その","その"],["声","こえ"],["を","を"],["聞く","きく","聞く",5],["と","と"],["、"],["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["仕事","しごと"],["を","を"],["やめて","やめて","やめて",3],["、"],["山","やま"],["へ","へ"],["走りました","はしりました","走る",2],["。"]]],"tr":{"az":"Bir gün oğlanın ağlına maraqlı bir fikir gəldi. Dağdan kəndə baxanda çoxlu insanın gəzdiyini gördü. Oğlan ucadan dəfələrlə «Canavar var! Kömək edin!» deyə qışqırdı. Kəndlilər onun səsini eşidən kimi işlərini saxlayıb dağa qaçdılar.","en":"One day, the boy had an amusing idea. When he looked down at the village from the mountain, he saw many people walking around. He shouted, “Wolf! Help!” again and again. When the villagers heard his voice, they stopped working and ran up the mountain.","ru":"Однажды мальчику пришла в голову забавная мысль. Когда он посмотрел с горы на деревню, то увидел много людей. Он несколько раз громко закричал: «Волк! Помогите!» Услышав его голос, жители деревни бросили работу и побежали в гору."}},{"t":[[["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["橋","はし"],["を","を"],["渡って","わたって","渡って",3],["、"],["森","もり"],["の","の"],["角","かど"],["を","を"],["曲がりました","まがりました","曲がる",2],["。"],["でも","でも"],["、"],["山","やま"],["に","に"],["着く","つく","着く",5],["と","と"],["、"],["オオカミ","オオカミ"],["は","は"],["いませんでした","いませんでした","いる",4],["。"],["少年","しょうねん"],["は","は"],["「"],["ははは","ははは"],["、"],["うそ","うそ"],["だ","だ","です"],["よ","よ"],["！"],["」"],["と","と"],["言って","いって","言う",3],["、"],["笑いました","わらいました","笑う",2],["。"],["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["怒って","おこって","怒る",3],["、"],["「"],["うそ","うそ"],["を","を"],["言わないでください","いわないでください","言う",18],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Kəndlilər körpüdən keçib meşə yolunun döngəsindən döndülər. Amma dağa çatanda orada canavar yox idi. Oğlan «Ha-ha-ha, zarafat etdim!» deyib güldü. Kəndlilər əsəbiləşərək «Yalan danışma, zəhmət olmasa» dedilər.","en":"The villagers crossed the bridge and turned at the bend in the forest path. But when they reached the mountain, there was no wolf. The boy laughed and said, “Ha ha ha! I was lying!” The villagers became angry and said, “Please don't tell lies.”","ru":"Жители деревни перешли мост и повернули на лесной тропинке. Но когда они добрались до горы, волка там не было. Мальчик рассмеялся и сказал: «Ха-ха-ха! Я вас обманул!» Жители рассердились и сказали: «Пожалуйста, не обманывай нас»."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["も","も"],["、"],["少年","しょうねん"],["は","は"],["一人","ひとり"],["でした","でした","です",9],["。"],["暇な","ひまな","暇",1],["とき","とき"],["、"],["昨日","きのう"],["の","の"],["こと","こと"],["を","を"],["思い出しました","おもいだしました","思い出す",2],["。"],["そして","そして"],["、"],["また","また"],["「"],["オオカミ","オオカミ"],["だ","だ","です"],["！"],["」"],["と","と"],["叫びました","さけびました","叫ぶ",2],["。"],["村","むら"],["の","の"],["人たち","ひとたち"],["が","が"],["来る","くる","来る",5],["と","と"],["、"],["少年","しょうねん"],["は","は"],["また","また"],["笑いました","わらいました","笑う",2],["。"],["みんな","みんな"],["は","は"],["何","なん"],["も","も"],["言わないで","いわないで","言う",18],["、"],["村","むら"],["へ","へ"],["帰りました","かえりました","帰る",2],["。"]]],"tr":{"az":"Ertəsi gün də oğlan tək idi. Boş vaxtında dünən baş verənləri xatırladı. Sonra yenə «Canavar var!» deyə qışqırdı. Kəndlilər gələndə oğlan yenə güldü. Hamı heç nə demədən kəndə qayıtdı.","en":"The next day, the boy was alone again. When he had nothing to do, he remembered what had happened the day before. Then he shouted, “Wolf!” again. When the villagers arrived, the boy laughed once more. Everyone returned to the village without saying anything.","ru":"На следующий день мальчик снова был один. Когда ему стало скучно, он вспомнил вчерашний случай. Затем он снова закричал: «Волк!» Когда жители деревни прибежали, мальчик опять засмеялся. Все молча вернулись в деревню."}},{"t":[[["三日目","みっかめ"],["の","の"],["夕方","ゆうがた"],["、"],["森","もり"],["から","から"],["変な","へんな","変",1],["音","おと"],["が","が"],["聞こえました","きこえました","聞こえる",2],["。"],["少年","しょうねん"],["が","が"],["後ろ","うしろ"],["を","を"],["見る","みる","見る",5],["と","と"],["、"],["大きな","おおきな"],["オオカミ","オオカミ"],["が","が"],["立っていました","たっていました","立つ",15],["。"],["オオカミ","オオカミ"],["は","は"],["羊","ひつじ"],["を","を"],["見る","みる","見る",5],["と","と"],["、"],["ゆっくり","ゆっくり"],["近く","ちかく"],["へ","へ"],["来ました","きました","来る",2],["。"],["少年","しょうねん"],["は","は"],["怖く","こわく","怖い"],["なって","なって","なる",3],["、"],["急いで","いそいで","急ぐ",13],["木","き"],["に","に"],["登りました","のぼりました","登りました",2],["。"]]],"tr":{"az":"Üçüncü gün axşamüstü meşədən qəribə bir səs gəldi. Oğlan arxaya baxanda böyük bir canavarın dayandığını gördü. Canavar qoyunları görən kimi yavaş-yavaş yaxınlaşdı. Oğlan çox qorxdu və tələsik ağaca dırmaşdı.","en":"On the evening of the third day, a strange sound came from the forest. When the boy looked behind him, he saw a big wolf standing there. When the wolf saw the sheep, it slowly came closer. The boy became frightened and quickly climbed a tree.","ru":"Вечером третьего дня из леса послышался странный звук. Когда мальчик оглянулся, он увидел большого волка. Увидев овец, волк начал медленно приближаться. Мальчик испугался и быстро залез на дерево."}},{"t":[[["少年","しょうねん"],["は","は"],["「"],["本当","ほんとう"],["の","の"],["オオカミ","オオカミ"],["だ","だ","です"],["！"],["助けて","たすけて","助ける",3],["！"],["」"],["と","と"],["何回","なんかい"],["も","も"],["叫びました","さけびました","叫ぶ",2],["。"],["でも","でも"],["、"],["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["その","その"],["声","こえ"],["を","を"],["聞いても","きいても","聞く",34],["、"],["山","やま"],["へ","へ"],["行きませんでした","いきませんでした","行く",4],["。"],["「"],["また","また"],["うそ","うそ"],["でしょう","でしょう","です"],["」"],["と","と"],["思った","おもった","思う",0],["から","から"],["です","です"],["。"],["少年","しょうねん"],["は","は"],["木","き"],["の","の"],["上","うえ"],["で","で"],["泣きました","なきました","泣く",2],["。"],["オオカミ","オオカミ"],["は","は"],["羊","ひつじ"],["を","を"],["一匹","いっぴき"],["連れて","つれて","連れて",3],["、"],["森","もり"],["へ","へ"],["行きました","いきました","行く",2],["。"]]],"tr":{"az":"Oğlan dəfələrlə «Bu dəfə həqiqətən canavar var! Kömək edin!» deyə qışqırdı. Amma kəndlilər onun səsini eşitsələr də, dağa getmədilər. Çünki yenə yalan danışdığını düşündülər. Oğlan ağacın üstündə ağladı. Canavar bir qoyunu götürüb meşəyə apardı.","en":"The boy shouted, “It's a real wolf! Help!” again and again. But even though the villagers heard him, they did not go to the mountain. They thought he was lying again. The boy cried in the tree. The wolf took one sheep away into the forest.","ru":"Мальчик много раз кричал: «Это настоящий волк! Помогите!» Но жители деревни слышали его крики и всё равно не пошли в горы. Они думали, что он снова обманывает. Мальчик плакал на дереве. Волк увёл одну овцу в лес."}},{"t":[[["夜","よる"],["に","に"],["なる","なる","なる",5],["前","まえ"],["に","に"],["、"],["少年","しょうねん"],["は","は"],["村","むら"],["へ","へ"],["帰りました","かえりました","帰る",2],["。"],["村","むら"],["の","の"],["人たち","ひとたち"],["に","に"],["本当","ほんとう"],["の","の"],["こと","こと"],["を","を"],["話して","はなして","話す",3],["、"],["「"],["ごめん","ごめん"],["なさい","なさい","なさる",10],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["村","むら"],["の","の"],["おじいさん","おじいさん"],["は","は"],["「"],["うそ","うそ"],["を","を"],["何回","なんかい"],["も","も"],["言う","いう","言う",5],["と","と"],["、"],["本当","ほんとう"],["の","の"],["とき","とき"],["も","も"],["だれ","だれ"],["も","も"],["信じません","しんじません","信じません",6],["よ","よ"],["」"],["と","と"],["教えました","おしえました","教える",2],["。"],["少年","しょうねん"],["は","は"],["静かに","しずかに","静か",8],["頭","あたま"],["を","を"],["下げました","さげました","下げました",2],["。"]]],"tr":{"az":"Gecə düşməmiş oğlan kəndə qayıtdı. Kəndlilərə həqiqəti danışıb «Bağışlayın» dedi. Kəndin yaşlı kişisi ona «Dəfələrlə yalan danışanda, həqiqəti söylədiyin vaxt da heç kim sənə inanmır» deyə başa saldı. Oğlan sakitcə başını aşağı əydi.","en":"Before nightfall, the boy returned to the village. He told the villagers the truth and said, “I'm sorry.” An old man explained, “If you lie again and again, no one will believe you even when you tell the truth.” The boy quietly bowed his head.","ru":"До наступления ночи мальчик вернулся в деревню. Он рассказал жителям правду и сказал: «Простите меня». Один старик объяснил ему: «Если много раз лгать, никто не поверит тебе, даже когда ты говоришь правду». Мальчик молча опустил голову."}},{"t":[[["それから","それから"],["、"],["少年","しょうねん"],["は","は"],["うそ","うそ"],["を","を"],["言わなく","いわなく","言う",19],["なりました","なりました","なる",2],["。"],["羊","ひつじ"],["の","の"],["世話","せわ"],["を","を"],["する","する","する",5],["とき","とき"],["、"],["いつ","いつ"],["も","も"],["まじめに","まじめに","まじめに",8],["働きました","はたらきました","働く",2],["。"],["ある","ある","ある(連体詞)"],["朝","あさ"],["、"],["森","もり"],["から","から"],["大きな","おおきな"],["音","おと"],["が","が"],["聞こえました","きこえました","聞こえる",2],["が","が"],["、"],["今度","こんど"],["は","は"],["オオカミ","オオカミ"],["で","で"],["は","は"],["ありませんでした","ありませんでした","ある",4],["。"],["小さな","ちいさな"],["羊","ひつじ"],["が","が"],["大きな","おおきな"],["くしゃみ","くしゃみ"],["を","を"],["した","した","する",0],["だけ","だけ"],["でした","でした","です",9],["。"],["少年","しょうねん"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["本当","ほんとう"],["の","の"],["こと","こと"],["も","も"],["、"],["おもしろい","おもしろい"],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"O vaxtdan sonra oğlan daha yalan danışmadı. Qoyunlara baxanda həmişə işini məsuliyyətlə gördü. Bir səhər meşədən gur səs gəldi, amma bu dəfə canavar deyildi. Balaca bir qoyun sadəcə çox bərk asqırmışdı. Oğlan gülərək «Həqiqətin özü də maraqlı ola bilərmiş» dedi.","en":"From then on, the boy stopped telling lies. Whenever he looked after the sheep, he worked responsibly. One morning, a loud sound came from the forest, but this time it was not a wolf. A little sheep had simply sneezed very loudly. The boy laughed and said, “The truth can be funny too!”","ru":"С тех пор мальчик перестал лгать. Когда он пас овец, то всегда добросовестно работал. Однажды утром из леса раздался громкий звук, но на этот раз это был не волк. Просто маленькая овечка очень громко чихнула. Мальчик рассмеялся и сказал: «Правда тоже бывает забавной!»"}}]},{"id":"l23b","ti":[[["空","そら"],["の","の"],["町","まち"],["と","と"],["星","ほし"],["の","の"],["道","みち"]]],"tt":{"az":"Səma şəhəri və ulduzlu yol","en":"The City in the Sky and the Starlit Path","ru":"Небесный город и звёздная дорога"},"P":[{"t":[[["ある日","あるひ"],["、"],["少年","しょうねん"],["の","の"],["ハル","ハル"],["は","は"],["、"],["古い","ふるい"],["時計","とけい"],["を","を"],["見つけました","みつけました","見つける",2],["。"],["時計","とけい"],["の","の"],["後ろ","うしろ"],["に","に"],["は","は"],["、"],["小さな","ちいさな"],["星","ほし"],["の","の"],["絵","え"],["が","が"],["ありました","ありました","ある",2],["。"],["ハル","ハル"],["が","が"],["時計","とけい"],["を","を"],["回す","まわす","回す",5],["と","と"],["、"],["青い","あおい"],["光","ひかり"],["が","が"],["出ました","でました","出る",2],["。"],["目","め"],["を","を"],["開ける","あける","開ける",5],["と","と"],["、"],["ハル","ハル"],["は","は"],["空","そら"],["に","に"],["浮かぶ","うかぶ","浮かぶ",5],["不思議な","ふしぎな","不思議",1],["町","まち"],["に","に"],["いました","いました","いる",2],["。"]]],"tr":{"az":"Bir gün Haru adlı oğlan köhnə bir saat tapdı. Saatın arxa tərəfində balaca ulduz şəkli vardı. Haru saatı çevirəndə mavi işıq saçıldı. Gözlərini açanda özünü səmada üzən sehrli bir şəhərdə gördü.","en":"One day, a boy named Haru found an old watch. There was a small picture of a star on its back. When Haru turned the watch, a blue light appeared. When he opened his eyes, he was in a mysterious city floating in the sky.","ru":"Однажды мальчик по имени Хару нашёл старые часы. На задней стороне часов была маленькая звезда. Когда Хару повернул часы, появился голубой свет. Открыв глаза, он оказался в загадочном городе, парящем в небе."}},{"t":[[["町","まち"],["に","に"],["は","は"],["高い","たかい"],["建物","たてもの"],["と","と"],["金色","きんいろ"],["の","の"],["橋","はし"],["が","が"],["ありました","ありました","ある",2],["。"],["空","そら"],["に","に"],["は","は"],["魚","さかな"],["が","が"],["泳いでいて","およいでいて","泳ぐ",52],["、"],["道","みち"],["に","に"],["は","は"],["小さな","ちいさな"],["ロボット","ロボット"],["が","が"],["歩いていました","あるいていました","歩く",15],["。"],["ハル","ハル"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["「"],["ここ","ここ"],["は","は"],["どこ","どこ"],["です","です"],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["でも","でも"],["、"],["だれ","だれ"],["も","も"],["答えませんでした","こたえませんでした","答える",4],["。"],["知らない","しらない","知る",19],["町","まち"],["で","で"],["一人","ひとり"],["に","に"],["なる","なる","なる",5],["と","と"],["、"],["少し","すこし"],["寂しかった","さびしかった","寂しい",0],["です","です"],["。"]]],"tr":{"az":"Şəhərdə hündür binalar və qızılı körpülər vardı. Səmada balıqlar üzür, yollarda balaca robotlar gəzirdi. Haru təəccüblənərək «Bura haradır?» deyə soruşdu. Amma heç kim cavab vermədi. Tanımadığı şəhərdə tək qalanda özünü bir az tənha hiss etdi.","en":"The city had tall buildings and golden bridges. Fish swam through the sky, and little robots walked along the roads. Haru was surprised and asked, “Where am I?” But nobody answered. Being alone in an unfamiliar city made him feel a little lonely.","ru":"В городе были высокие здания и золотые мосты. По небу плавали рыбы, а по дорогам ходили маленькие роботы. Хару удивился и спросил: «Где я?» Но никто не ответил. Оказавшись один в незнакомом городе, он почувствовал себя немного одиноко."}},{"t":[[["ハル","ハル"],["は","は"],["家","いえ"],["へ","へ"],["帰る","かえる","帰る",5],["道","みち"],["を","を"],["探しました","さがしました","探しました",2],["。"],["大きな","おおきな"],["交差","こうさ"],["点","てん"],["に","に"],["来る","くる","来る",5],["と","と"],["、"],["信号","しんごう"],["が","が"],["赤く","あかく","赤い"],["なりました","なりました","なる",2],["。"],["青","あお"],["に","に"],["なる","なる","なる",5],["と","と"],["、"],["ハル","ハル"],["は","は"],["道","みち"],["を","を"],["渡りました","わたりました","渡りました",2],["。"],["それから","それから"],["角","かど"],["を","を"],["右","みぎ"],["へ","へ"],["曲がる","まがる","曲がる",5],["と","と"],["、"],["時計","とけい"],["の","の"],["形","かたち"],["の","の"],["店","みせ"],["が","が"],["ありました","ありました","ある",2],["。"],["店","みせ"],["の","の"],["前","まえ"],["に","に"],["は","は"],["白い","しろい"],["猫","ねこ"],["が","が"],["座っていました","すわっていました","座る",15],["。"]]],"tr":{"az":"Haru evə qayıdan yolu axtardı. Böyük yolayrıcına çatanda işıqfor qırmızı yandı. Yaşıl işıq yananda Haru yolu keçdi. Sonra tinə çatıb sağa dönəndə saat formasında bir mağaza gördü. Mağazanın qarşısında ağ pişik oturmuşdu.","en":"Haru searched for a way home. When he reached a large intersection, the traffic light turned red. When it turned green, Haru crossed the road. Then, when he turned right at the corner, he found a shop shaped like a clock. A white cat sat in front of it.","ru":"Хару стал искать дорогу домой. Когда он дошёл до большого перекрёстка, светофор загорелся красным. На зелёный свет Хару перешёл дорогу. Затем он повернул направо за угол и увидел магазин в форме часов. Перед магазином сидел белый кот."}},{"t":[[["猫","ねこ"],["は","は"],["「"],["家","いえ"],["へ","へ"],["帰りたい","かえりたい","帰る",30],["の","の"],["？"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["ハル","ハル"],["が","が"],["「"],["はい","はい"],["」"],["と","と"],["答える","こたえる","答える",5],["と","と"],["、"],["猫","ねこ"],["は","は"],["小さな","ちいさな"],["地図","ちず"],["を","を"],["出しました","だしました","出す",2],["。"],["「"],["この","この"],["道","みち"],["を","を"],["まっすぐ","まっすぐ"],["歩く","あるく","歩く",5],["と","と"],["、"],["星","ほし"],["の","の"],["橋","はし"],["が","が"],["あります","あります","ある",11],["。"],["でも","でも"],["、"],["橋","はし"],["を","を"],["渡る","わたる","渡る",5],["とき","とき"],["、"],["下","した"],["を","を"],["見ないで","みないで","見る",18],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["猫","ねこ"],["に","に"],["お礼","おれい"],["を","を"],["言って","いって","言う",3],["、"],["走りました","はしりました","走る",2],["。"]]],"tr":{"az":"Pişik «Evə qayıtmaq istəyirsən?» deyə soruşdu. Haru «Bəli» cavabını verəndə pişik balaca bir xəritə çıxardı. «Bu yolla düz getsən, Ulduz körpüsünə çatacaqsan. Amma körpüdən keçəndə aşağı baxma» dedi. Haru pişiyə təşəkkür edib qaçdı.","en":"The cat asked, “Do you want to go home?” When Haru answered, “Yes,” the cat took out a small map. “If you walk straight along this road, you'll find the Star Bridge. But when you cross it, don't look down,” the cat said. Haru thanked the cat and ran off.","ru":"Кот спросил: «Хочешь вернуться домой?» Когда Хару ответил: «Да», кот достал маленькую карту. «Если пойдёшь прямо по этой дороге, найдёшь Звёздный мост. Но когда будешь переходить его, не смотри вниз», – сказал кот. Хару поблагодарил его и побежал."}},{"t":[[["橋","はし"],["の","の"],["前","まえ"],["に","に"],["着く","つく","着く",5],["と","と"],["、"],["大きな","おおきな"],["ロボット","ロボット"],["が","が"],["立っていました","たっていました","立つ",15],["。"],["ロボット","ロボット"],["は","は"],["故障","こしょう"],["していて","していて","する",46],["、"],["変な","へんな","変",1],["音","おと"],["を","を"],["出していました","だしていました","出す",15],["。"],["ハル","ハル"],["が","が"],["近く","ちかく"],["へ","へ"],["行く","いく","行く",5],["と","と"],["、"],["ロボット","ロボット"],["は","は"],["「"],["たすけて","たすけて","たすけて",3],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["小さな","ちいさな"],["ボタン","ボタン"],["に","に"],["触りました","さわりました","触る",2],["が","が"],["、"],["何","なん"],["も","も"],["変わりませんでした","かわりませんでした","変わる",4],["。"]]],"tr":{"az":"Körpünün qarşısına çatanda orada böyük bir robot dayanmışdı. Robot xarab olmuşdu və qəribə səslər çıxarırdı. Haru yaxınlaşanda robot «Kömək et» dedi. Haru balaca bir düyməyə toxundu, amma heç nə dəyişmədi.","en":"When Haru reached the bridge, a large robot was standing in front of it. The robot was broken and making strange noises. When Haru approached, the robot said, “Help me.” Haru touched a small button, but nothing changed.","ru":"Когда Хару дошёл до моста, перед ним стоял большой робот. Робот сломался и издавал странные звуки. Когда Хару подошёл ближе, робот сказал: «Помоги мне». Хару коснулся маленькой кнопки, но ничего не изменилось."}},{"t":[[["ハル","ハル"],["は","は"],["時計","とけい"],["の","の"],["後ろ","うしろ"],["の","の"],["星","ほし"],["を","を"],["思い出しました","おもいだしました","思い出す",2],["。"],["時計","とけい"],["を","を"],["出して","だして","出す",3],["、"],["横","よこ"],["の","の"],["小さな","ちいさな"],["つまみ","つまみ"],["を","を"],["回しました","まわしました","回しました",2],["。"],["する","する","する",5],["と","と"],["、"],["時計","とけい"],["から","から"],["光","ひかり"],["が","が"],["出て","でて","出る",3],["、"],["ロボット","ロボット"],["の","の"],["体","からだ"],["が","が"],["光りました","ひかりました","光る",2],["。"],["ロボット","ロボット"],["は","は"],["元気","げんき"],["に","に"],["なって","なって","なる",3],["、"],["「"],["ありがとう","ありがとう"],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["橋","はし"],["の","の"],["上","うえ"],["の","の"],["暗い","くらい"],["道","みち"],["を","を"],["明るく","あかるく","明るい"],["しました","しました","する",2],["。"]]],"tr":{"az":"Haru saatın arxasındakı ulduzu xatırladı. Saatı çıxarıb yanındakı balaca çarxı çevirdi. Bu zaman saatdan işıq çıxdı və robotun bədəni parladı. Robot düzəlib «Çox sağ ol!» dedi. Sonra körpünün üstündəki qaranlıq yolu işıqlandırdı.","en":"Haru remembered the star on the back of his watch. He took out the watch and turned the little knob on its side. Light shone from the watch, and the robot's body began to glow. The robot recovered and said, “Thank you!” Then it lit up the dark path across the bridge.","ru":"Хару вспомнил звезду на задней стороне часов. Он достал часы и повернул маленькое колёсико сбоку. Из часов полился свет, и тело робота засветилось. Робот снова заработал и сказал: «Спасибо!» Затем он осветил тёмную дорогу на мосту."}},{"t":[[["ハル","ハル"],["は","は"],["橋","はし"],["を","を"],["渡りました","わたりました","渡りました",2],["。"],["下","した"],["を","を"],["見ないで","みないで","見る",18],["歩く","あるく","歩く",5],["と","と"],["、"],["橋","はし"],["の","の"],["終わり","おわり"],["に","に"],["青い","あおい"],["ドア","ドア"],["が","が"],["見えました","みえました","見える",2],["。"],["ドア","ドア"],["を","を"],["引く","ひく","引く",5],["と","と"],["、"],["暖かい","あたたかい"],["風","かぜ"],["が","が"],["吹きました","ふきました","吹きました",2],["。"],["ハル","ハル"],["は","は"],["中","なか"],["に","に"],["入りました","はいりました","入る",2],["。"],["する","する","する",5],["と","と"],["、"],["いつ","いつ"],["も","も"],["の","の"],["自分","じぶん"],["の","の"],["部屋","へや"],["に","に"],["戻りました","もどりました","戻る",2],["。"]]],"tr":{"az":"Haru körpüdən keçdi. Aşağı baxmadan yeriyəndə körpünün sonunda mavi bir qapı gördü. Qapını özünə çəkib açanda isti külək əsdi. Haru içəri girdi. Bir də baxdı ki, öz otağına qayıdıb.","en":"Haru crossed the bridge. As he walked without looking down, he saw a blue door at the far end. When he pulled the door open, a warm wind blew. Haru stepped inside. Suddenly, he was back in his own room.","ru":"Хару перешёл мост. Когда он шёл, не глядя вниз, то увидел синюю дверь в конце моста. Он потянул дверь на себя, и подул тёплый ветер. Хару вошёл внутрь. И вдруг оказался в своей комнате."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["ハル","ハル"],["が","が"],["起きる","おきる","起きる",5],["と","と"],["、"],["時計","とけい"],["は","は"],["普通","ふつう"],["の","の"],["時計","とけい"],["に","に"],["なっていました","なっていました","なる",15],["。"],["「"],["夢","ゆめ"],["だった","だった","です",9],["の","の"],["か","か"],["な","な"],["」"],["と","と"],["思いました","おもいました","思う",2],["。"],["でも","でも"],["、"],["机","つくえ"],["の","の"],["上","うえ"],["に","に"],["は","は"],["小さな","ちいさな"],["金色","きんいろ"],["の","の"],["魚","さかな"],["が","が"],["いました","いました","いる",2],["。"],["魚","さかな"],["は","は"],["空","そら"],["を","を"],["泳ぎながら","およぎながら","泳ぐ",43],["、"],["「"],["また","また"],["来て","きて","来る",3],["ね","ね"],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["次","つぎ"],["は","は"],["地図","ちず"],["を","を"],["持って行こう","もっていこう","持つ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Ertəsi səhər Haru oyananda saat adi saata çevrilmişdi. «Görəsən, yuxu idi?» deyə düşündü. Amma masanın üstündə balaca qızılı balıq vardı. Balıq havada üzərək «Yenə gəl!» dedi. Haru gülərək «Gələn dəfə özümlə xəritə apararam» söylədi.","en":"When Haru woke up the next morning, the watch had become an ordinary watch. “Was it a dream?” he wondered. But a tiny golden fish was floating above his desk. Swimming through the air, the fish said, “Come again!” Haru laughed and said, “Next time, I'll bring a map!”","ru":"На следующее утро, когда Хару проснулся, часы стали обычными. «Может быть, это был сон?» – подумал он. Но над столом плавала маленькая золотая рыбка. Плавая по воздуху, рыбка сказала: «Приходи ещё!» Хару рассмеялся и ответил: «В следующий раз возьму с собой карту!»"}}]},{"id":"l23c","ti":[[["おばあさん","おばあさん"],["の","の"],["不思議な","ふしぎな","不思議",1],["道","みち"],["案内","あんない"]]],"tt":{"az":"Nənənin qəribə yol göstərişi","en":"Grandma's Mysterious Directions","ru":"Загадочные указания бабушки"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["土曜","どよう"],["日","ひ"],["、"],["大学生","だいがくせい"],["の","の"],["ユキ","ユキ"],["は","は"],["新しい","あたらしい"],["町","まち"],["へ","へ"],["引っ越しました","ひっこしました","引っ越しました",2],["。"],["新しい","あたらしい"],["部屋","へや"],["は","は"],["静か","しずか"],["で","で"],["、"],["窓","まど"],["が","が"],["大きかった","おおきかった","大きい",0],["です","です"],["。"],["でも","でも"],["、"],["近く","ちかく"],["の","の"],["道","みち"],["は","は"],["まだ","まだ"],["よく","よく"],["分かりませんでした","わかりませんでした","分かる",4],["。"],["朝","あさ"],["、"],["母","はは"],["から","から"],["電話","でんわ"],["が","が"],["来て","きて","来る",3],["、"],["「"],["駅","えき"],["の","の"],["近く","ちかく"],["の","の"],["おばあちゃん","おばあちゃん"],["に","に"],["会い","あい","会う",10],["に","に"],["行って","いって","行く",3],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Bir şənbə günü Yuki adlı universitet tələbəsi yeni bir şəhərə köçdü. Yeni otağı sakit idi və böyük pəncərəsi vardı. Amma yaxınlıqdakı yolları hələ yaxşı tanımırdı. Səhər anası zəng edib «Vağzalın yaxınlığında yaşayan nənənə baş çəkməyi unutma» dedi.","en":"One Saturday, a university student named Yuki moved to a new town. Her new room was quiet and had a large window. But she did not know the nearby roads very well yet. That morning, her mother called and said, “Remember to visit Grandma near the station.”","ru":"Однажды в субботу студентка Юки переехала в новый город. Её новая комната была тихой, с большим окном. Но Юки ещё плохо знала местные дороги. Утром мама позвонила ей и сказала: «Не забудь навестить бабушку, которая живёт рядом со станцией»."}},{"t":[[["ユキ","ユキ"],["は","は"],["駅","えき"],["へ","へ"],["行く","いく","行く",5],["道","みち"],["を","を"],["調べました","しらべました","調べる",2],["。"],["でも","でも"],["、"],["携帯","けいたい"],["電話","でんわ"],["は","は"],["故障","こしょう"],["していて","していて","する",46],["、"],["地図","ちず"],["が","が"],["見られませんでした","みられませんでした","見る",53],["。"],["困った","こまった","困る",0],["とき","とき"],["、"],["道","みち"],["の","の"],["角","かど"],["に","に"],["小さな","ちいさな"],["花屋","はなや"],["が","が"],["ありました","ありました","ある",2],["。"],["店","みせ"],["の","の"],["おばあさん","おばあさん"],["に","に"],["道","みち"],["を","を"],["聞く","きく","聞く",5],["と","と"],["、"],["にこにこ","にこにこ"],["して","して","する",3],["教えてくれました","おしえてくれました","教える",54],["。"]]],"tr":{"az":"Yuki vağzala gedən yolu axtardı. Amma telefonu xarab olduğu üçün xəritəyə baxa bilmədi. Nə edəcəyini bilməyəndə küçənin tinində balaca bir gül dükanı gördü. Dükanın yaşlı sahibəsindən yolu soruşanda qadın gülümsəyərək ona istiqaməti izah etdi.","en":"Yuki tried to look up the way to the station. But her phone was broken, so she could not see the map. While she was wondering what to do, she noticed a small flower shop on the corner. When she asked the elderly shopkeeper for directions, the woman smiled and helped her.","ru":"Юки попыталась найти дорогу к станции. Но её телефон сломался, и она не могла посмотреть карту. Пока она думала, что делать, на углу улицы заметила маленький цветочный магазин. Юки спросила дорогу у пожилой хозяйки магазина, и та с улыбкой всё объяснила."}},{"t":[[["おばあさん","おばあさん"],["は","は"],["「"],["この","この"],["道","みち"],["を","を"],["まっすぐ","まっすぐ"],["歩く","あるく","歩く",5],["と","と"],["、"],["大きな","おおきな"],["交差","こうさ"],["点","てん"],["が","が"],["あります","あります","ある",11],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["「"],["信号","しんごう"],["が","が"],["青","あお"],["に","に"],["なった","なった","なる",0],["とき","とき"],["、"],["道","みち"],["を","を"],["渡ってください","わたってください","渡ってください",35],["。"],["それから","それから"],["右","みぎ"],["へ","へ"],["曲がる","まがる","曲がる",5],["と","と"],["、"],["古い","ふるい"],["橋","はし"],["が","が"],["あります","あります","ある",11],["。"],["橋","はし"],["を","を"],["渡る","わたる","渡る",5],["と","と"],["、"],["駅","えき"],["です","です"],["よ","よ"],["」"],["と","と"],["教えました","おしえました","教える",2],["。"],["ユキ","ユキ"],["は","は"],["お礼","おれい"],["を","を"],["言って","いって","言う",3],["、"],["歩き","あるき","歩く",10],["始めました","はじめました","始める",2],["。"]]],"tr":{"az":"Yaşlı qadın «Bu yolla düz getsən, böyük bir yolayrıcına çatacaqsan» dedi. «İşıqfor yaşıl yananda yolu keç. Sonra sağa dönəndə köhnə bir körpü görəcəksən. Körpünü keçsən, vağzala çatacaqsan» deyə izah etdi. Yuki təşəkkür edib yola düşdü.","en":"The elderly woman said, “If you walk straight along this road, you'll reach a large intersection.” She continued, “When the traffic light turns green, cross the road. Then turn right, and you'll see an old bridge. Cross the bridge, and you'll reach the station.” Yuki thanked her and started walking.","ru":"Пожилая женщина сказала: «Если пойдёшь прямо, дойдёшь до большого перекрёстка». Она продолжила: «Когда загорится зелёный свет, перейди дорогу. Затем поверни направо и увидишь старый мост. Перейдёшь мост и окажешься у станции». Юки поблагодарила её и пошла."}},{"t":[[["ユキ","ユキ"],["は","は"],["言われた","いわれた","言う",55],["とおり","とおり"],["に","に"],["歩きました","あるきました","歩く",2],["。"],["でも","でも"],["、"],["橋","はし"],["を","を"],["渡る","わたる","渡る",5],["と","と"],["、"],["駅","えき"],["で","で"],["は","は"],["なく","なく","ない"],["大きな","おおきな"],["公園","こうえん"],["が","が"],["ありました","ありました","ある",2],["。"],["公園","こうえん"],["の","の"],["中","なか"],["に","に"],["は","は"],["古い","ふるい"],["建物","たてもの"],["と","と"],["広い","ひろい"],["駐車場","ちゅうしゃじょう"],["が","が"],["ありました","ありました","ある",2],["。"],["ユキ","ユキ"],["は","は"],["「"],["道","みち"],["を","を"],["間違えた","まちがえた","間違えた",0],["か","か"],["な","な"],["」"],["と","と"],["思いました","おもいました","思う",2],["。"],["その","その"],["とき","とき"],["、"],["小さな","ちいさな"],["犬","いぬ"],["が","が"],["ユキ","ユキ"],["の","の"],["前","まえ"],["に","に"],["来ました","きました","来る",2],["。"]]],"tr":{"az":"Yuki ona deyilən yolla getdi. Amma körpünü keçəndə vağzal əvəzinə böyük bir park gördü. Parkın içində köhnə bina və geniş dayanacaq vardı. Yuki «Görəsən, yolu səhv salmışam?» deyə düşündü. Elə bu vaxt balaca bir it onun qabağına çıxdı.","en":"Yuki followed the directions exactly. But when she crossed the bridge, she found a large park instead of the station. Inside the park were an old building and a spacious parking lot. “Did I take the wrong way?” Yuki wondered. Just then, a little dog appeared in front of her.","ru":"Юки пошла точно по указанному маршруту. Но, перейдя мост, вместо станции увидела большой парк. В парке находились старое здание и просторная парковка. «Неужели я ошиблась дорогой?» – подумала Юки. В этот момент перед ней появилась маленькая собака."}},{"t":[[["犬","いぬ"],["は","は"],["赤い","あかい"],["首輪","くびわ"],["を","を"],["していました","していました","する",15],["。"],["首輪","くびわ"],["に","に"],["は","は"],["「"],["モモ","モモ"],["」"],["と","と"],["書いてありました","かいてありました","書く",36],["。"],["ユキ","ユキ"],["が","が"],["名前","なまえ"],["を","を"],["呼ぶ","よぶ","呼ぶ",5],["と","と"],["、"],["犬","いぬ"],["は","は"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["走りました","はしりました","走る",2],["。"],["ユキ","ユキ"],["が","が"],["止まる","とまる","止まる",5],["と","と"],["、"],["犬","いぬ"],["も","も"],["止まりました","とまりました","止まる",2],["。"],["「"],["もし","もし"],["か","か"],["して","して","する",3],["、"],["道","みち"],["を","を"],["教えてくれる","おしえてくれる","教える",56],["の","の"],["？"],["」"],["と","と"],["ユキ","ユキ"],["は","は"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"İtin boynunda qırmızı xalta vardı. Xaltasında «Momo» yazılmışdı. Yuki adını çağıranda it sevinclə qaçmağa başladı. Yuki dayananda it də dayandı. Yuki gülərək «Yoxsa mənə yolu göstərmək istəyirsən?» dedi.","en":"The dog wore a red collar. The name “Momo” was written on it. When Yuki called its name, the dog ran happily. When Yuki stopped, the dog stopped too. Yuki laughed and said, “Are you trying to show me the way?”","ru":"На собаке был красный ошейник. На нём было написано «Момо». Когда Юки позвала собаку по имени, та радостно побежала. Когда Юки останавливалась, собака тоже останавливалась. Юки улыбнулась и сказала: «Ты хочешь показать мне дорогу?»"}},{"t":[[["犬","いぬ"],["に","に"],["ついて行く","ついていく","つく"],["と","と"],["、"],["公園","こうえん"],["の","の"],["奥","おく"],["に","に"],["小さな","ちいさな"],["家","いえ"],["が","が"],["ありました","ありました","ある",2],["。"],["家","いえ"],["の","の"],["前","まえ"],["に","に"],["は","は"],["、"],["さっき","さっき"],["の","の"],["花屋","はなや"],["の","の"],["おばあさん","おばあさん"],["が","が"],["立っていました","たっていました","立つ",15],["。"],["ユキ","ユキ"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["「"],["どう","どう"],["して","して","する",3],["ここ","ここ"],["に","に"],["いる","いる","いる",5],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["おばあさん","おばあさん"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["ここ","ここ"],["は","は"],["私","わたし"],["の","の"],["家","いえ"],["です","です"],["よ","よ"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Yuki itin arxasınca gedəndə parkın dərinliyində balaca bir ev gördü. Evin qarşısında bayaqkı gül dükanının yaşlı sahibəsi dayanmışdı. Yuki təəccüblənərək «Siz niyə buradasınız?» deyə soruşdu. Yaşlı qadın gülüb «Bura mənim evimdir» cavabını verdi.","en":"When Yuki followed the dog, she found a small house deep inside the park. The elderly woman from the flower shop was standing in front of it. Yuki was surprised and asked, “Why are you here?” The woman laughed and replied, “This is my house.”","ru":"Когда Юки пошла за собакой, в глубине парка она увидела маленький дом. Перед домом стояла та самая пожилая женщина из цветочного магазина. Юки удивилась и спросила: «Почему вы здесь?» Женщина рассмеялась и ответила: «Это мой дом»."}},{"t":[[["その","その"],["とき","とき"],["、"],["家","いえ"],["の","の"],["中","なか"],["から","から"],["ユキ","ユキ"],["の","の"],["母","はは"],["が","が"],["出てきました","でてきました","出る",23],["。"],["「"],["ユキ","ユキ"],["、"],["びっくり","びっくり"],["した","した","する",0],["？"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["実","じつ"],["は","は"],["、"],["花屋","はなや"],["の","の"],["おばあさん","おばあさん"],["は","は"],["ユキ","ユキ"],["の","の"],["おばあちゃん","おばあちゃん"],["でした","でした","です",9],["。"],["ユキ","ユキ"],["は","は"],["子ども","こども"],["の","の"],["とき","とき"],["から","から"],["何","なん"],["年","ねん"],["も","も"],["会っていなかった","あっていなかった","会う",57],["の","の"],["で","で"],["、"],["顔","かお"],["を","を"],["覚えていませんでした","おぼえていませんでした","覚えていませんでした",28],["。"],["母","はは"],["と","と"],["おばあちゃん","おばあちゃん"],["は","は"],["、"],["ユキ","ユキ"],["の","の"],["ため","ため"],["に","に"],["小さな","ちいさな"],["パーティー","パーティー"],["を","を"],["準備","じゅんび"],["していました","していました","する",15],["。"]]],"tr":{"az":"Bu vaxt evdən Yukinin anası çıxdı. «Yuki, təəccübləndin?» deyə soruşdu. Məlum oldu ki, gül dükanındakı yaşlı qadın elə Yukinin öz nənəsi imiş. Yuki uşaqlığından bəri uzun illər onu görmədiyi üçün üzünü xatırlamırdı. Anası ilə nənəsi Yuki üçün balaca bir məclis hazırlamışdılar.","en":"Just then, Yuki's mother came out of the house. “Yuki, are you surprised?” she asked. In fact, the elderly flower shop owner was Yuki's own grandmother. Yuki had not seen her for many years, since she was a child, so she did not remember her face. Her mother and grandmother had prepared a little party for her.","ru":"В этот момент из дома вышла мама Юки. «Юки, удивилась?» – спросила она. Оказалось, что пожилая хозяйка цветочного магазина была родной бабушкой Юки. Юки не видела её много лет, с самого детства, и поэтому не помнила её лица. Мама и бабушка подготовили для Юки небольшой праздник."}},{"t":[[["みんな","みんな"],["で","で"],["ケーキ","ケーキ"],["を","を"],["食べた","たべた","食べる",0],["とき","とき"],["、"],["ユキ","ユキ"],["は","は"],["おばあちゃん","おばあちゃん"],["に","に"],["聞きました","ききました","聞く",2],["。"],["「"],["でも","でも"],["、"],["どう","どう"],["して","して","する",3],["駅","えき"],["へ","へ"],["の","の"],["道","みち"],["を","を"],["教えなかった","おしえなかった","教える",22],["の","の"],["？"],["」"],["おばあちゃん","おばあちゃん"],["は","は"],["「"],["駅","えき"],["へ","へ"],["行く","いく","行く",5],["より","より"],["、"],["ここ","ここ"],["へ","へ"],["来る","くる","来る",5],["ほう","ほう"],["が","が"],["楽しいでしょう","たのしいでしょう","楽しい"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"],["モモ","モモ"],["も","も"],["大きな","おおきな"],["声","こえ"],["で","で"],["「"],["ワン","ワン"],["！"],["」"],["と","と"],["鳴きました","なきました","鳴く",2],["。"],["その","その"],["日","ひ"],["から","から"],["、"],["ユキ","ユキ"],["は","は"],["道","みち"],["に","に"],["迷った","まよった","迷った",0],["とき","とき"],["、"],["地図","ちず"],["だけ","だけ"],["で","で"],["なく","なく","ない"],["、"],["人","ひと"],["に","に"],["も","も"],["道","みち"],["を","を"],["聞く","きく","聞く",5],["ように","ように","よう",8],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Hamı birlikdə tort yeyəndə Yuki nənəsindən soruşdu: «Amma niyə mənə vağzalın yolunu göstərmədin?» Nənəsi gülərək «Vağzala getməkdənsə, bura gəlmək daha maraqlıdır, elə deyil?» dedi. Momo da ucadan «Hav!» deyə hürdü. O gündən sonra Yuki yolunu itirəndə təkcə xəritəyə baxmır, insanlardan da yol soruşurdu.","en":"While everyone was eating cake, Yuki asked her grandmother, “But why didn't you tell me the way to the station?” Grandma laughed and said, “Coming here is more fun than going to the station, isn't it?” Momo barked loudly, “Woof!” From that day on, whenever Yuki got lost, she asked people for directions instead of relying only on maps.","ru":"Когда все вместе ели торт, Юки спросила бабушку: «Но почему ты не показала мне дорогу к станции?» Бабушка рассмеялась и сказала: «Ведь прийти сюда веселее, чем идти на станцию, правда?» Момо тоже громко гавкнула: «Гав!» С того дня, когда Юки терялась, она не только смотрела на карту, но и спрашивала дорогу у людей."}}]}],"G":{"ありがとう":{"b":"ありがとう","p":"ex","m":{"az":"sağ ol","en":"thank you","ru":"спасибо"},"n":{"az":"Daha nəzakətli: ありがとうございます.","en":"More polite: ありがとうございます.","ru":"Вежливее: ありがとうございます."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おばあちゃん":{"b":"おばあちゃん","p":"n","m":{"az":"nənə; yaşlı qadın","en":"grandma; elderly woman","ru":"бабушка; пожилая женщина"},"n":{"az":"Nənəyə və ya yaşlı qadına mehriban müraciət kimi də işlənir.","en":"Also used as an affectionate address to a grandmother or elderly woman.","ru":"Также используется как ласковое обращение к бабушке или пожилой женщине."}},"おもしろい":{"b":"おもしろい","p":"ai","m":{"az":"maraqlı, əyləncəli","en":"interesting, amusing","ru":"интересный, забавный"},"n":{"az":"い-sifətdir və həm maraqlı, həm də gülməli mənasında işlənə bilər.","en":"An i-adjective that can mean either interesting or amusing.","ru":"Прилагательное на い, которое может означать интересный или забавный."}},"お礼":{"b":"お礼 (おれい)","p":"n","m":{"az":"təşəkkür; minnətdarlıq","en":"thanks; gratitude","ru":"благодарность"},"n":{"az":"お礼を言う təşəkkür etmək, お礼に isə minnətdarlıq əlaməti olaraq deməkdir.","en":"お礼を言う means to express thanks; お礼に means as a token of gratitude.","ru":"お礼を言う означает поблагодарить, а お礼に в знак благодарности."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"ごめん":{"b":"ごめん","p":"n","m":{"az":"üzr; bağışlanma","en":"apology; forgiveness","ru":"извинение; прощение"},"n":{"az":"ごめん gündəlik danışıqda üzr istəmək üçün işlənir.","en":"ごめん is an informal way to apologize.","ru":"ごめん используется для неформального извинения."}},"さっき":{"b":"さっき","p":"n","m":{"az":"bayaq, bir az əvvəl","en":"a moment ago","ru":"только что"}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"だれ":{"b":"だれ","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"Sual sözü: あの人はだれですか = O adam kimdir? Daha nəzakətli forması どなた.","en":"Question word: あの人はだれですか = Who is that person? More polite: どなた.","ru":"Вопросительное слово: あの人はだれですか = Кто этот человек? Вежливее: どなた."}},"つく":{"b":"つく (着く)","p":"v","m":{"az":"çatmaq, yetişmək","en":"to arrive, to reach","ru":"прибывать, добираться"},"n":{"az":"I qrup feldir: 駅に着く = stansiyaya çatmaq; つきませんでした = çatmadı.","en":"A Group 1 verb: 駅に着く = to arrive at the station; つきませんでした = did not arrive.","ru":"Глагол I группы: 駅に着く = прибыть на станцию; つきませんでした = не прибыл."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"どこ":{"b":"どこ","p":"pr","m":{"az":"hara","en":"where","ru":"где, куда"},"n":{"az":"どこの国 = hansı ölkə.","en":"どこの国 = which country.","ru":"どこの国 = какая страна."}},"ない":{"b":"無い (ない)","p":"ai","m":{"az":"yoxdur; mövcud deyil","en":"not exist; not have","ru":"нет; отсутствует"},"n":{"az":"İ-sifət kimi dəyişir: なく və なかった; felə qoşulduqda inkar da bildirir.","en":"Inflects like an i-adjective: なく and なかった; attached to a verb, it also marks negation.","ru":"Изменяется как и-прилагательное: なく и なかった; при глаголе также выражает отрицание."}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にこにこ":{"b":"にこにこ","p":"ad","m":{"az":"gülümsəyərək","en":"with a cheerful smile","ru":"с улыбкой"},"n":{"az":"にこにこする = gülümsəmək, adətən səssiz və şən şəkildə.","en":"にこにこする means to smile cheerfully, usually without laughing aloud.","ru":"にこにこする означает приветливо улыбаться, обычно без громкого смеха."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"はい":{"b":"はい","p":"in","m":{"az":"bəli, hə","en":"yes","ru":"да"},"n":{"az":"Həm 'bəli', həm də 'eşidirəm, buyurun' mənasında işlənir.","en":"Means 'yes' and also 'I hear you / here you are'.","ru":"Значит 'да', а также 'слушаю / вот, пожалуйста'."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほう":{"b":"方 (ほう)","p":"n","m":{"az":"tərəf, istiqamət, seçim","en":"side, direction, option","ru":"сторона, направление, вариант"},"n":{"az":"〜のほう müqayisədə üstün tutulan tərəfi bildirə bilər.","en":"〜のほう can indicate the preferred side in a comparison.","ru":"〜のほう может указывать на предпочтительный вариант при сравнении."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"ケーキ":{"b":"ケーキ","p":"n","m":{"az":"tort, pirojna","en":"cake","ru":"торт, пирожное"}},"ドア":{"b":"ドア","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"ハル":{"b":"ハル","p":"nm","m":{"az":"Haru","en":"Haru","ru":"Хару"}},"ボタン":{"b":"ボタン","p":"n","m":{"az":"düymə","en":"button","ru":"кнопка; пуговица"},"n":{"az":"Həm cihaz düyməsi, həm də geyim düyməsi üçün işlənir.","en":"Used for both device buttons and clothing buttons.","ru":"Употребляется для кнопок устройств и пуговиц одежды."}},"ユキ":{"b":"ユキ","p":"nm","m":{"az":"Yuki (qız adı, 'qar' deməkdir)","en":"Yuki (girl's name, means 'snow')","ru":"Юки (имя, значит 'снег')"}},"ロボット":{"b":"ロボット","p":"n","m":{"az":"robot","en":"robot","ru":"робот"},"n":{"az":"Katakana ilə yazılır, çünki xarici mənşəli sözdür.","en":"Written in katakana because it is a loanword.","ru":"Пишется катаканой, так как это заимствование."}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一匹":{"b":"一匹 (いっぴき)","p":"nu","m":{"az":"bir heyvan, bir ədəd","en":"one small animal","ru":"одно животное"},"n":{"az":"匹 kiçik heyvanlar üçündür, 一匹 いっぴき oxunur.","en":"匹 counts small animals, and 一匹 is pronounced いっぴき.","ru":"Счётный суффикс 匹 для небольших животных, 一匹 читается いっぴき."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"不思議":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli; qəribə","en":"mysterious; curious","ru":"загадочный; удивительный"},"n":{"az":"な-sifətidir: 不思議な話; isim kimi «sirr, möcüzə» də bildirir.","en":"A な-adjective: 不思議な話; as a noun it can mean a mystery or wonder.","ru":"な-прилагательное: 不思議な話; как существительное может означать тайну или чудо."}},"世話":{"b":"世話 (せわ)","p":"n","m":{"az":"qayğı, qulluq","en":"care, looking after","ru":"забота, уход"},"n":{"az":"Nの世話をする “N-ə baxmaq, qulluq etmək” deməkdir.","en":"Nの世話をする means “look after N.”","ru":"Nの世話をする означает «заботиться о N, ухаживать за N»."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人たち":{"b":"人たち (ひとたち)","p":"n","m":{"az":"adamlar, camaat","en":"people","ru":"люди"}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"会う":{"b":"会う (あう)","p":"v","m":{"az":"görüşmək, rastlaşmaq","en":"meet, see someone","ru":"встречаться, встречать"},"n":{"az":"Görüşülən şəxs に və ya と ilə işlənir: 友達に会う “dostla görüşmək”; て-forması 会って olur.","en":"The person met takes に or と, as in 友達に会う “meet a friend”; the て-form is 会って.","ru":"Человек, с которым встречаются, обозначается с に или と: 友達に会う «встретиться с другом»; форма на て: 会って."}},"体":{"b":"体 (からだ)","p":"n","m":{"az":"bədən","en":"body","ru":"тело"}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"働く":{"b":"働く (はたらく)","p":"v","m":{"az":"işləmək","en":"to work","ru":"работать"},"n":{"az":"İş yerini で göstərir: 銀行で働きます.","en":"The workplace takes で: 銀行で働きます.","ru":"Место работы обозначается через で: 銀行で働きます."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"光":{"b":"光 (ひかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"公園":{"b":"公園 (こうえん)","p":"n","m":{"az":"park","en":"park","ru":"парк"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"分かる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"to understand","ru":"понимать"},"n":{"az":"Adətən N が分かる işlənir; 分かりませんでした başa düşmədim deməkdir.","en":"Usually takes が; 分かりませんでした means did not understand.","ru":"Обычно используется с が; 分かりませんでした означает не понял."}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"叫ぶ":{"b":"叫ぶ (さけぶ)","p":"v","m":{"az":"qışqırmaq; hayqırmaq","en":"to shout; to cry out","ru":"кричать; восклицать"}},"右":{"b":"右 (みぎ)","p":"n","m":{"az":"sağ, sağ tərəf","en":"right, right side","ru":"право, правая сторона"},"n":{"az":"右に = sağa; 右の手 = sağ əl.","en":"右に = to the right; 右の手 = right hand.","ru":"右に = направо; 右の手 = правая рука."}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"土曜":{"b":"土曜 (どよう)","p":"n","m":{"az":"şənbə","en":"Saturday","ru":"суббота"},"n":{"az":"土曜日 sözünün qısa formasıdır.","en":"Short for 土曜日.","ru":"Сокращение от 土曜日."}},"地図":{"b":"地図 (ちず)","p":"n","m":{"az":"xəritə","en":"map","ru":"карта"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"変":{"b":"変 (へん)","p":"an","m":{"az":"qəribə","en":"strange; odd","ru":"странный"},"n":{"az":"な-sifətidir: 変な音 = qəribə səs.","en":"A な-adjective: 変な音 = a strange sound.","ru":"な-прилагательное: 変な音 = странный звук."}},"変わる":{"b":"変わる (かわる)","p":"v","m":{"az":"dəyişmək","en":"to change","ru":"меняться"},"n":{"az":"変わる özü dəyişmək, 変える isə nəyisə dəyişdirmək deməkdir.","en":"変わる means to change by itself; 変える means to change something.","ru":"変わる означает меняться, а 変える означает менять что-либо."}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"夢":{"b":"夢 (ゆめ)","p":"n","m":{"az":"yuxu, arzu","en":"dream","ru":"сон, мечта"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"天気":{"b":"天気 (てんき)","p":"n","m":{"az":"hava, hava şəraiti","en":"weather","ru":"погода"}},"奥":{"b":"奥 (おく)","p":"n","m":{"az":"içəri tərəf; dərinlik","en":"inner part; back","ru":"глубина; дальняя часть"},"n":{"az":"Yerə görə otağın içəri tərəfini, mağazanın arxasını və ya meşənin dərinliyini bildirir.","en":"Depending on the place, it means the inner part of a room, the back of a shop, or deep inside a forest.","ru":"В зависимости от места обозначает глубину комнаты, дальнюю часть магазина или глубь леса."}},"始める":{"b":"始める (はじめる)","p":"v","m":{"az":"başlamaq, başlatmaq","en":"to begin, to start something","ru":"начинать"},"n":{"az":"Təsirli feldir, 勉強を始めます dərsə başlamaqdır, təsirsiz qarşılığı 始まる-dur.","en":"Transitive: 勉強を始めます means start studying, while 始まる is intransitive.","ru":"Переходный глагол: 勉強を始めます - начать учёбу, непереходный вариант 始まる."}},"子ども":{"b":"子ども (こども)","p":"n","m":{"az":"uşaq","en":"child","ru":"ребёнок"}},"実":{"b":"実 (み)","p":"n","m":{"az":"meyvə, bar, toxum","en":"fruit, berry, seed","ru":"плод, ягода, семя"},"n":{"az":"実がなる - ağacın və ya bitkinin bar verməsi.","en":"実がなる means for a tree or plant to bear fruit.","ru":"実がなる означает плодоносить."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"寂しい":{"b":"寂しい (さびしい)","p":"ai","m":{"az":"tənha, kədərli, darıxmış","en":"lonely, sad","ru":"одинокий, тоскливый"},"n":{"az":"い-sifətdir; 寂しく forması zərf kimi və ya başqa quruluşlarda işlənir.","en":"An i-adjective; 寂しく is used adverbially or in other constructions.","ru":"Это i-прилагательное; 寂しく используется как наречие или в других конструкциях."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"少年":{"b":"少年 (しょうねん)","p":"n","m":{"az":"oğlan, yeniyetmə oğlan","en":"boy, young lad","ru":"мальчик, юноша"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"年":{"b":"年 (とし)","p":"n","m":{"az":"yaş; il","en":"age; year","ru":"возраст; год"},"n":{"az":"Burada 'yaş' mənasında とし oxunur. İl sayğacı kimi ねん: 二年.","en":"Here 'age', read とし. As a year counter: ねん.","ru":"Здесь 'возраст', читается とし. Как счёт лет – ねん."}},"広い":{"b":"広い (ひろい)","p":"ai","m":{"az":"geniş, böyük sahəli","en":"wide, spacious","ru":"широкий, просторный"},"n":{"az":"い-sifətdir; əksi 狭い - dar.","en":"An i-adjective; its opposite is 狭い, narrow.","ru":"Это i-прилагательное; антоним 狭い - узкий."}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"建物":{"b":"建物 (たてもの)","p":"n","m":{"az":"bina; tikili","en":"building; structure","ru":"здание; строение"}},"形":{"b":"形 (かたち)","p":"n","m":{"az":"forma, şəkil","en":"shape, form","ru":"форма"}},"後ろ":{"b":"後ろ (うしろ)","p":"n","m":{"az":"arxa, arxa tərəf","en":"back, behind","ru":"задняя сторона, позади"},"n":{"az":"Nの後ろ bir şeyin arxasını bildirir: 家の後ろ evin arxası.","en":"Nの後ろ means behind something: 家の後ろ, behind the house.","ru":"Nの後ろ означает «позади чего-либо»: 家の後ろ, за домом."}},"怒る":{"b":"怒る (おこる)","p":"v","m":{"az":"hirslənmək; danlamaq","en":"to get angry; to scold","ru":"сердиться; ругать"},"n":{"az":"Hirslənmək üçün 人に怒る, danlamaq üçün 人を怒る işlənir.","en":"人に怒る means to be angry with someone; 人を怒る means to scold someone.","ru":"人に怒る означает сердиться на кого-то, а 人を怒る означает ругать кого-то."}},"怖い":{"b":"怖い (こわい)","p":"ai","m":{"az":"qorxulu, vahiməli","en":"scary, frightening","ru":"страшный, пугающий"},"n":{"az":"い-sifətdir: 怖い話 = qorxulu hekayə; 怖くない = qorxulu deyil.","en":"An i-adjective: 怖い話 = scary story; 怖くない = not scary.","ru":"Прилагательное на い: 怖い話 = страшная история; 怖くない = не страшно."}},"思い出す":{"b":"思い出す (おもいだす)","p":"v","m":{"az":"xatırlamaq, yada salmaq","en":"remember, recall","ru":"вспоминать"}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"戻る":{"b":"戻る (もどる)","p":"v","m":{"az":"qayıtmaq; geri dönmək","en":"return; go back","ru":"возвращаться"},"n":{"az":"Təsirsiz feldir; 戻す nəyisə geri qaytarmaq deməkdir.","en":"An intransitive verb; 戻す means to put or bring something back.","ru":"Непереходный глагол; 戻す означает вернуть что-либо."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"明るい":{"b":"明るい (あかるい)","p":"ai","m":{"az":"işıqlı, parlaq","en":"bright","ru":"светлый, яркий"},"n":{"az":"明るく光る = parlaq işıq saçmaq.","en":"明るく光る = shine brightly.","ru":"明るく光る = ярко светиться."}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時計":{"b":"時計 (とけい)","p":"n","m":{"az":"saat","en":"clock; watch","ru":"часы"}},"普通":{"b":"普通 (ふつう)","p":"n","m":{"az":"adilik; adi hal","en":"normality; usual state","ru":"обычность; обычное состояние"},"n":{"az":"普通の adi, 普通に adi qaydada, ayrıca 普通 isə adətən mənasında işlənə bilər.","en":"普通の means ordinary, 普通に means normally, and 普通 alone can mean usually.","ru":"普通の означает обычный, 普通に обычным образом, а 普通 отдельно может означать обычно."}},"暇":{"b":"暇 (ひま)","p":"an","m":{"az":"boş vaxt, boş, məşğul olmayan","en":"free time, free, unoccupied","ru":"свободное время, свободный"},"n":{"az":"な-sifət kimi 暇な人, isim kimi 暇がある işlənir.","en":"Used as a na-adjective in 暇な人 or as a noun in 暇がある.","ru":"Употребляется как na-прилагательное в 暇な人 или как существительное в 暇がある."}},"暖かい":{"b":"暖かい (あたたかい)","p":"ai","m":{"az":"isti, ilıq","en":"warm","ru":"тёплый"},"n":{"az":"İ-sifətidir; əsasən hava və mühitin istiliyini, 温かい isə əşya, yemək və münasibətin istiliyini bildirir.","en":"An i-adjective mainly describing warm weather or surroundings; 温かい is used for objects, food, and personal warmth.","ru":"Прилагательное на い, обычно о тёплой погоде или обстановке; 温かい употребляется о предметах, еде и душевном тепле."}},"暗い":{"b":"暗い (くらい)","p":"ai","m":{"az":"qaranlıq, tutqun","en":"dark, gloomy","ru":"тёмный, мрачный"},"n":{"az":"İ-sifətidir və həm zəif işığı, həm də tutqun əhvalı bildirə bilər.","en":"An i-adjective that can describe low light or a gloomy mood.","ru":"Прилагательное на い, описывающее слабое освещение или мрачное настроение."}},"曲がる":{"b":"曲がる (まがる)","p":"v","m":{"az":"dönmək; əyilmək","en":"to turn; to bend","ru":"поворачивать; изгибаться"},"n":{"az":"角を曲がる küçənin tinindən dönmək deməkdir.","en":"角を曲がる means to turn at a corner.","ru":"角を曲がる означает повернуть за угол."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"机":{"b":"机 (つくえ)","p":"n","m":{"az":"yazı masası","en":"desk","ru":"письменный стол"}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"横":{"b":"横 (よこ)","p":"n","m":{"az":"yan; böyür","en":"side; beside","ru":"бок; рядом"},"n":{"az":"Nの横 = N-in yanı; üfüqi istiqamət mənası da var.","en":"Nの横 means beside N; 横 can also refer to a horizontal direction.","ru":"Nの横 означает рядом с N; 横 также обозначает горизонтальное направление."}},"橋":{"b":"橋 (はし)","p":"n","m":{"az":"körpü","en":"bridge","ru":"мост"}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"母":{"b":"母 (はは)","p":"n","m":{"az":"ana","en":"mother","ru":"мать"},"n":{"az":"Başqaları ilə danışarkən öz ananı bildirmək üçün işlənir; anaya müraciətdə adətən お母さん deyilir.","en":"Used for one's own mother when speaking to others; お母さん is usual when addressing her.","ru":"Употребляется о своей матери в разговоре с другими; при обращении к ней обычно используется お母さん."}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"泳ぐ":{"b":"泳ぐ (およぐ)","p":"v","m":{"az":"üzmək","en":"to swim","ru":"плавать"},"n":{"az":"泳ぎたくない - üzmək istəmirəm; 〜たい istək, 〜たくない isə inkar bildirir.","en":"泳ぎたくない means not wanting to swim; 〜たい expresses desire and 〜たくない negates it.","ru":"泳ぎたくない означает не хочу плавать; 〜たい выражает желание, а 〜たくない - отрицание."}},"犬":{"b":"犬 (いぬ)","p":"n","m":{"az":"it","en":"dog","ru":"собака"}},"猫":{"b":"猫 (ねこ)","p":"n","m":{"az":"pişik","en":"cat","ru":"кошка"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"絵":{"b":"絵 (え)","p":"n","m":{"az":"şəkil, rəsm","en":"picture, drawing","ru":"картина, рисунок"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"花屋":{"b":"花屋 (はなや)","p":"n","m":{"az":"gül dükanı, gülçü","en":"flower shop, florist","ru":"цветочный магазин, флорист"}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見える":{"b":"見える (みえる)","p":"v","m":{"az":"görünmək","en":"to be visible, to appear","ru":"быть видным"},"n":{"az":"道が見えました = yol göründü (が ilə).","en":"道が見えました = a path came into view.","ru":"道が見えました = показалась дорога."}},"見つける":{"b":"見つける (みつける)","p":"v","m":{"az":"tapmaq; aşkar etmək","en":"find; discover","ru":"находить; обнаруживать"},"n":{"az":"Təsirli feldir; 見つかる tapılmaq deməkdir.","en":"A transitive verb; 見つかる means to be found.","ru":"Переходный глагол; 見つかる означает найтись."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"角":{"b":"角 (かど)","p":"n","m":{"az":"künc; tin","en":"corner","ru":"угол"},"n":{"az":"Küçə tini üçün かど, buynuz üçün isə つの oxunur.","en":"Read かど for a street corner and つの for an animal horn.","ru":"Читается かど для угла улицы и つの для рога животного."}},"触る":{"b":"触る (さわる)","p":"v","m":{"az":"toxunmaq","en":"to touch","ru":"трогать; прикасаться"},"n":{"az":"Adətən N に触る şəklində işlənir: ボタンに触る.","en":"Usually takes に: ボタンに触る means to touch a button.","ru":"Обычно используется с に: ボタンに触る означает касаться кнопки."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"起きる":{"b":"起きる (おきる)","p":"v","m":{"az":"oyanmaq; yataqdan qalxmaq","en":"to wake up; to get up","ru":"просыпаться; вставать"},"n":{"az":"Təsirsizdir; 起こす kimisə oyatmaq deməkdir.","en":"Intransitive; 起こす means to wake someone up.","ru":"Непереходный; 起こす означает будить кого-то."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"金色":{"b":"金色 (きんいろ)","p":"n","m":{"az":"qızılı rəng","en":"gold color","ru":"золотой цвет"},"n":{"az":"金色に光る = qızılı rəngdə parlamaq.","en":"金色に光る = shine gold.","ru":"金色に光る = сиять золотом."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"電話":{"b":"電話 (でんわ)","p":"n","m":{"az":"telefon; telefon zəngi","en":"telephone; phone call","ru":"телефон; звонок"},"n":{"az":"電話する və 電話をかける telefonla zəng etmək deməkdir.","en":"電話する and 電話をかける both mean to make a phone call.","ru":"電話する и 電話をかける означают звонить по телефону."}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"頭":{"b":"頭 (あたま)","p":"n","m":{"az":"baş","en":"head","ru":"голова"}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"高い":{"b":"高い (たかい)","p":"ai","m":{"az":"hündür; baha","en":"high; expensive","ru":"высокий; дорогой"},"n":{"az":"い-sifətdir; 高かった keçmiş formadır.","en":"It is an i-adjective; 高かった is its past form.","ru":"Это i-прилагательное; 高かった - форма прошедшего времени."}},"魚":{"b":"魚 (さかな)","p":"n","m":{"az":"balıq","en":"fish","ru":"рыба"}},"鳴く":{"b":"鳴く (なく)","p":"v","m":{"az":"heyvan səsi çıxarmaq; ötmək","en":"make an animal sound; chirp","ru":"издавать голос; петь о птицах"},"n":{"az":"Heyvan və quş səsləri üçün işlənir; insanın ağlaması eyni oxunuşlu 泣く ilə yazılır.","en":"Used for animal and bird cries; human crying is written 泣く with the same reading.","ru":"Употребляется для голосов животных и птиц; человеческий плач записывается 泣く с тем же чтением."}}}};